/* A BAR CHART WITH ITS SCALE ON IT.
 *
 * It used to be five grey blocks and one blue one, with no axis, no grid and no
 * number anywhere: a picture of a chart rather than a chart (owner, 23.08). The
 * shape is the same; what was missing is everything that makes a shape
 * readable — where zero is, how far the ticks are apart, what the column under
 * the pointer actually says, and what the goal line means.
 *
 * The scale, the grid, the goal line, the readout, the legend and the row of
 * labels are NOT here: they are the same furniture on every chart in this
 * system and they live in src/lib/chart.css. What is here is the MARK — the
 * columns, their colours and how they answer the pointer.
 */
.bar-chart {
  /* Local to this component: the three heights a bar chart is read at, the
   * width the scale column reserves, the bar's own cap, and the column a
   * horizontal chart gives its names. */
  --chart-height: calc(var(--space-16) * 1.75);
  --chart-scale-width: 2.5rem;
  --bar-chart-bar-width: 2.5rem;

  /* Set per element from the data, and declared here so the stylesheet stands
   * on its own: a bar with no value has no length, and that is not a crash. */
  --tick-at: 0%;
  --bar-size: 0%;
  --bar-delay: 0ms;
  --readout-at: 50%;

  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin: 0;
  min-inline-size: 0;
}
.bar-chart[data-size="sm"] { --chart-height: var(--space-16); }
.bar-chart[data-size="lg"] { --chart-height: calc(var(--space-16) * 2.5); }

.bar-chart-plot {
  position: relative;
  flex: 1 1 auto;
  display: flex;
  align-items: flex-end;
  gap: var(--space-2);
  block-size: 100%;
  min-inline-size: 0;
}

/* THE COLUMN IS THE HIT AREA, and it is a button so a keyboard reaches the
 * same readout the pointer does. */
.bar-chart-column {
  position: relative;
  flex: 1 1 0;
  min-inline-size: 0;
  block-size: 100%;
  display: flex;
  align-items: flex-end;
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
  /* Reads, does not navigate: the data cursor, not the link one. */
  cursor: crosshair;
}
.bar-chart-column:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-sm);
}

.bar-chart-bars {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  /* 2px between adjacent fills, so two bars of the same colour still read as
   * two bars. Same gap the stacked segments use. */
  gap: var(--space-2xs);
  inline-size: 100%;
  block-size: 100%;
}
.bar-chart[data-stacked] .bar-chart-bars { flex-direction: column-reverse; align-items: center; }

.bar-chart-bar {
  position: relative;
  inline-size: min(100%, var(--bar-chart-bar-width));
  block-size: var(--bar-size);
  min-block-size: var(--space-2xs);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  background: var(--chart-1);
  /* The bar grows out of the baseline it is measured from, one after another
   * across the chart. `both` holds it at zero through its own delay. */
  transform-origin: bottom;
  animation: bar-chart-grow var(--duration-slow) var(--ease-out) var(--bar-delay) both;
}
.bar-chart[data-stacked] .bar-chart-bar { border-radius: var(--radius-sm); }

@keyframes bar-chart-grow {
  from { transform: scaleY(0); }
  to   { transform: scaleY(1); }
}

/* THE SERIES SLOTS, in fixed order. A chart with one series paints slot 1, so a
 * single-measure chart is the brand's own colour. */
.bar-chart-bar[data-series="2"] { background: var(--chart-2); }
.bar-chart-bar[data-series="3"] { background: var(--chart-3); }
.bar-chart-bar[data-series="4"] { background: var(--chart-4); }
.bar-chart-bar[data-series="5"] { background: var(--chart-5); }
.bar-chart-bar[data-series="6"] { background: var(--chart-6); }
/* A series that MEANS a status takes the status colour instead of its slot. */
.bar-chart-bar[data-tone="success"] { background: var(--chart-success); }
.bar-chart-bar[data-tone="warning"] { background: var(--chart-warning); }
.bar-chart-bar[data-tone="danger"]  { background: var(--chart-danger); }

/* The whole chart in one status tone, for a single-series chart that is about
 * one thing being good or bad. */
.bar-chart[data-tone="neutral"] .bar-chart-bar[data-series="1"] { background: var(--foreground); }
.bar-chart[data-tone="success"] .bar-chart-bar[data-series="1"] { background: var(--chart-success); }
.bar-chart[data-tone="warning"] .bar-chart-bar[data-series="1"] { background: var(--chart-warning); }
.bar-chart[data-tone="danger"]  .bar-chart-bar[data-series="1"] { background: var(--chart-danger); }

/* ONE COLUMN UNDER DISCUSSION: the rest step back rather than the accent
 * shouting. Only when the caller actually named one — `:has` keeps that
 * conditional in the stylesheet instead of an attribute on the figure. */
.bar-chart:has(.bar-chart-bar[data-emphasis]) .bar-chart-bar:not([data-emphasis]) { opacity: 0.4; }
/* And the column under the pointer is the one being read. */
.bar-chart:has(.bar-chart-column[data-active]) .bar-chart-column:not([data-active]) .bar-chart-bar { opacity: 0.55; }
/* It is never the dim one. The `:has` here is not decoration: the emphasis rule
 * above scores (0,5,0) and a plain descendant version of this one scored
 * (0,4,0), so with an emphasis set, hovering any OTHER column left the bar
 * being read at 0.4 while its neighbours sat at 0.55 — the one bar the reader
 * asked about was the palest thing on the chart. */
.bar-chart:has(.bar-chart-column[data-active]) .bar-chart-column[data-active] .bar-chart-bar { opacity: 1; }

.bar-chart-value {
  position: absolute;
  inset-block-end: 100%;
  inset-inline: 0;
  padding-block-end: var(--space-1);
  text-align: center;
  font-size: var(--font-xs);
  color: var(--chart-axis);
  font-variant-numeric: tabular-nums;
}

/* ── LYING DOWN ───────────────────────────────────────────────────────────────
 * The same chart for a RANKING: long names read better beside their bar than
 * rotated under it, and the eye compares lengths down a column. */
.bar-chart[data-orientation="horizontal"] .chart-frame { display: block; block-size: auto; }
.bar-chart[data-orientation="horizontal"] .bar-chart-plot {
  flex-direction: column;
  align-items: stretch;
  block-size: auto;
  gap: var(--space-3);
}
.bar-chart[data-orientation="horizontal"] .bar-chart-column {
  block-size: auto;
  flex-direction: column;
  align-items: stretch;
  gap: var(--space-1);
}
/* Name on the left of its own line, value on the right, bar underneath across
 * the whole width. */
.bar-chart-head {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  font-size: var(--font-xs);
  color: var(--chart-axis);
}
.bar-chart-head-value {
  margin-inline-start: auto;
  color: var(--foreground);
  font-variant-numeric: tabular-nums;
}
.bar-chart[data-orientation="horizontal"] .bar-chart-bars {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  block-size: auto;
}
.bar-chart[data-orientation="horizontal"] .bar-chart-bar {
  inline-size: var(--bar-size);
  block-size: var(--space-3);
  min-inline-size: var(--space-2xs);
  /* BOTH ENDS ROUNDED, lying down. Standing up, a bar's foot sits ON the zero
   * line the grid draws, so a square foot reads as anchored; lying down there
   * is no line at the start and a square end reads as a bar somebody cut off
   * (owner, 23.08). */
  border-radius: var(--radius-full);
  transform-origin: inline-start;
  animation-name: bar-chart-grow-inline;
}
@keyframes bar-chart-grow-inline {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}
.bar-chart-name {
  min-inline-size: 0;
  text-align: start;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bar-chart[data-orientation="horizontal"] .chart-grid {
  inset-block: 0;
  inset-inline: auto;
  inset-inline-start: var(--tick-at);
  border-block-start: 0;
  border-inline-start: 1px solid var(--chart-grid);
}

/* In a card the chart takes the spare height. Cards in a row are the same
 * height (owner's rule, 23.08), so a card whose subject is a chart gets extra
 * room — and the honest place for it is the plot, not a band of white between
 * the plot and the footer. Its own height stays the floor. */
.card > .bar-chart { flex: 1 1 auto; }
.card > .bar-chart .chart-frame {
  block-size: auto;
  min-block-size: var(--chart-height);
  flex: 1 1 auto;
}
/* Lying down there is no plot height to grow into, so the spare room goes
 * BETWEEN the rows: three bars stacked at the top of a card with 100px of
 * white under them is the hole this rule closes. */
.card > .bar-chart[data-orientation="horizontal"] .chart-frame { min-block-size: 0; }
.card > .bar-chart[data-orientation="horizontal"] .bar-chart-plot {
  block-size: 100%;
  justify-content: space-evenly;
}

import '../../lib/chart.css'
import './BarChart.css'
import { type CSSProperties, useState } from 'react'
import { cn } from '../lib/cn'
import { formatValue, scaleFor } from '../lib/chart'

type Tone = 'neutral' | 'primary' | 'success' | 'warning' | 'danger'
type Size = 'sm' | 'md' | 'lg'
type Orientation = 'vertical' | 'horizontal'

export type Bar = {
  /** What this column is: a period, a category, a site. */
  label: string
  /** The one measure, when the chart carries one. */
  value?: number
  /** One number per entry of `series`, when it carries several. */
  values?: number[]
}

export type BarSeries = {
  /** What this measure is. It names the colour in the legend and in the readout. */
  label: string
  /** A status tone instead of the next series colour — for shares that MEAN
   *  open / late / done. Mixing the two makes one series look like a warning. */
  tone?: Extract<Tone, 'success' | 'warning' | 'danger'>
}

type Props = {
  /** The columns, in the order they are read. */
  data: Bar[]
  /** Names the measures in `values`. Two or more turn the chart into a grouped
   *  (or `stacked`) one and bring a legend with them. */
  series?: BarSeries[]
  /** Segments of one column instead of columns side by side: for parts of a
   *  whole per period. Only with `series`. */
  stacked?: boolean
  /** Bars run across instead of up. The answer for long category names and for
   *  a ranking, where the eye compares lengths down a column of labels. */
  orientation?: Orientation
  /** Top of the scale. Defaults to the first nice number above the data; pass
   *  it when several charts must share one scale. */
  max?: number
  /** A goal drawn across the columns, so a bar can be short OF something. Its
   *  own label is deliberately not a prop: a word printed inside the plot sits
   *  on the data (owner, 23.08). Name the goal in the card's meta line. */
  target?: number
  /** The one column that carries the accent — the current period, the site
   *  under discussion. Single-series charts only; the others stay quiet. */
  emphasis?: string
  tone?: Tone
  size?: Size
  /** The scale down the side, and the grid lines with it. On by default: a bar
   *  with no scale is a shape, and the reader cannot say how big it is. */
  axis?: boolean
  /** Values printed on every bar. Off by default — the readout under the
   *  pointer says it for the one bar being read, which is what a reader asks. */
  showValues?: boolean
  /** What the chart measures. Required in practice: it names the chart for a
   *  screen reader, which then reads the table this component renders for it. */
  label?: string
  /** BCP-47 tag for the numbers. Omit to follow the browser. */
  locale?: string
  className?: string
}

/* Which way the readout hangs off its column. Centred over the middle of the
 * plot, and pinned by one edge over the first and last columns, so it never
 * leaves the card it is being read in. */
function side(at: number, count: number): 'start' | 'center' | 'end' {
  if (count < 3) return 'center'
  if (at === 0) return 'start'
  if (at === count - 1) return 'end'
  return 'center'
}

/* "Aug: Closed 52, Open 8" — the column's whole readout as one string, built
 * outside the JSX because a template inside a template inside a map is not
 * something anyone reads twice. */
function readout(category: string, parts: [string, string][]): string {
  const said = parts.map(([name, value]) => (name ? `${name} ${value}` : value)).join(', ')
  return `${category}: ${said}`
}

/** A value per category, as bars: the analytical card's second form after
 *  <Sparkline> (a value over time). Carries its own scale, grid, legend and
 *  hover readout, and reads as a table to a screen reader. Reach for <Meter>
 *  when there is one value against one target, and for a <Table> when the
 *  numbers are compared exactly rather than at a glance. 
 *
 * Copy: category labels are the categories' own names, short enough to sit under
 * a bar without turning. The accessible label says what is being counted
 * and over what.
 */
export function BarChart({
  data,
  series,
  stacked,
  orientation = 'vertical',
  max,
  target,
  emphasis,
  tone = 'primary',
  size,
  axis = true,
  showValues,
  label,
  locale,
  className,
}: Props) {
  const [at, setAt] = useState<number | null>(null)

  if (!data.length) return null

  /* One measure or several, the rest of the component works on the same shape.
   * The unnamed single series stays unnamed: a readout that says "Findings
   * closed per month 52" repeats the card's own title at the reader. */
  const measures: { label: string; tone?: BarSeries['tone'] }[] = series ?? [{ label: '' }]
  const rows = data.map((d) => ({
    label: d.label,
    values: d.values ?? [d.value ?? 0],
  }))

  /* Stacked columns are read as their total, so that is what the scale has to
   * hold; grouped ones are read bar by bar. */
  const peaks = rows.map((r) => (stacked ? r.values.reduce((sum, v) => sum + v, 0) : Math.max(...r.values)))
  const scale = scaleFor([...peaks, ...(max != null ? [max] : []), ...(target != null ? [target] : [])])
  const top = max ?? scale.max
  const pct = (v: number) => `${Math.max(0, Math.min(100, (v / top) * 100))}%`

  const format = (v: number) => formatValue(v, locale)
  const ticks = max != null ? scaleFor([max]).ticks : scale.ticks

  return (
    <figure
      className={cn('bar-chart', className)}
      data-tone={tone}
      data-size={size}
      data-orientation={orientation}
      data-stacked={stacked ? '' : undefined}
      data-axis={axis ? '' : undefined}
      onMouseLeave={() => setAt(null)}
    >
      <div className="chart-frame">
        {axis && (
          <div className="chart-scale" aria-hidden="true">
            {ticks.map((t) => (
              <span key={t} className="chart-tick" style={{ '--tick-at': pct(t) } as CSSProperties}>
                {format(t)}
              </span>
            ))}
          </div>
        )}

        <div className="bar-chart-plot">
          {axis &&
            ticks.map((t) => (
              <span key={t} className="chart-grid" style={{ '--tick-at': pct(t) } as CSSProperties} aria-hidden="true" />
            ))}

          {target != null && (
            <span className="chart-target" style={{ '--tick-at': pct(target) } as CSSProperties} aria-hidden="true" />
          )}

          {rows.map((row, i) => (
            /* A button, not a div with a mouse handler: the readout is reachable
               by keyboard and announced, and the whole column is the hit area. */
            <button
              type="button"
              key={row.label}
              className="bar-chart-column"
              data-active={at === i ? '' : undefined}
              aria-label={readout(row.label, row.values.map((v, k) => [measures[k]?.label ?? '', format(v)]))}
              onMouseEnter={() => setAt(i)}
              onFocus={() => setAt(i)}
              onBlur={() => setAt(null)}
            >
              {/* Lying down, the name sits OVER its own bar rather than in a
                  column beside it: a names column costs the bars a sixth of the
                  card's width, and the bar is the thing being compared (owner,
                  23.08: why is it not the full width). */}
              {orientation === 'horizontal' && (
                <span className="bar-chart-head">
                  <span className="bar-chart-name">{row.label}</span>
                  {showValues && <span className="bar-chart-head-value">{format(row.values[0])}</span>}
                </span>
              )}
              <span className="bar-chart-bars">
                {row.values.map((v, k) => (
                  <span
                    key={measures[k]?.label ?? k}
                    className="bar-chart-bar"
                    data-series={k + 1}
                    data-tone={measures[k]?.tone}
                    data-emphasis={emphasis === row.label ? '' : undefined}
                    style={{ '--bar-size': pct(v), '--bar-delay': `${i * 40}ms` } as CSSProperties}
                  >
                    {showValues && orientation === 'vertical' && <span className="bar-chart-value">{format(v)}</span>}
                  </span>
                ))}
              </span>
            </button>
          ))}

          {at != null && (
            <div
              className="chart-readout"
              data-side={side(at, rows.length)}
              style={{ '--readout-at': `${((at + 0.5) / rows.length) * 100}%` } as CSSProperties}
              aria-hidden="true"
            >
              <span className="chart-readout-label">{rows[at].label}</span>
              {rows[at].values.map((v, k) => (
                <span key={measures[k]?.label ?? k} className="chart-readout-row">
                  {series && <span className="chart-key" data-series={k + 1} data-tone={measures[k]?.tone} />}
                  {series && <span>{measures[k]?.label}</span>}
                  <span className="chart-readout-value">{format(v)}</span>
                </span>
              ))}
            </div>
          )}
        </div>
      </div>

      {orientation === 'vertical' && (
        <div className="chart-labels" aria-hidden="true">
          {rows.map((row, i) => (
            <span key={row.label} data-active={at === i ? '' : undefined}>
              {row.label}
            </span>
          ))}
        </div>
      )}

      {series && series.length > 1 && (
        <ul className="chart-legend" aria-hidden="true">
          {series.map((s, k) => (
            <li key={s.label}>
              <span className="chart-key" data-series={k + 1} data-tone={s.tone} />
              {s.label}
            </li>
          ))}
        </ul>
      )}

      {/* The data itself, for a screen reader and for anyone who cannot use
          colour: a chart is a rendering of a table, so the table is what is
          announced rather than a sentence somebody wrote about the shape. */}
      <table className="sr-only">
        {label && <caption>{label}</caption>}
        <thead>
          <tr>
            <th scope="col">Category</th>
            {measures.map((m, k) => (
              <th scope="col" key={m.label || k}>
                {m.label || label || 'Value'}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.label}>
              <th scope="row">{row.label}</th>
              {row.values.map((v, k) => (
                <td key={measures[k]?.label ?? k}>{format(v)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}
